-- Table: budget_allocation_detail
-- Source: accounting_admin_db.sql (2. Accounting core and budget)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS budget_allocation_detail (
    id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    budget_allocation_id   BIGINT NOT NULL REFERENCES budget_allocation(id) ON DELETE CASCADE,
    line_number            INTEGER NOT NULL CHECK (line_number > 0),
    budget_plan_detail_id  BIGINT REFERENCES budget_plan_detail(id),
    coa_id                 BIGINT NOT NULL REFERENCES masterdata_coa(id),
    department_id          BIGINT REFERENCES masterdata_department(id),
    allocated_amount       NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (allocated_amount >= 0),
    used_amount            NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (used_amount >= 0),
    notes                  TEXT,
    UNIQUE (budget_allocation_id, line_number)
);
